    /// <summary>
    /// Specifies the behavior of the non-volatile registers when resetting the device.
    /// </summary>
    [Flags]
    public enum ResetFlags : byte
    {
        /// <summary>
        /// All reset flags are cleared.
        /// </summary>
        [Description("All reset flags are cleared.")]
        None = 0x0,

        /// <summary>
        /// The device will boot with all the registers reset to their default factory values.
        /// </summary>
        [Description("The device will boot with all the registers reset to their default factory values.")]
        RestoreDefault = 0x1,

        /// <summary>
        /// The device will boot and restore all the registers to the values stored in non-volatile memory.
        /// </summary>
        [Description("The device will boot and restore all the registers to the values stored in non-volatile memory.")]
        RestoreEeprom = 0x2,

        /// <summary>
        /// The device will boot and save all the current register values to non-volatile memory.
        /// </summary>
        [Description("The device will boot and save all the current register values to non-volatile memory.")]
        Save = 0x4,

        /// <summary>
        /// The device will boot with the default device name.
        /// </summary>
        [Description("The device will boot with the default device name.")]
        RestoreName = 0x8,

        /// <summary>
        /// The device will enter firmware update mode.
        /// </summary>
        [Description("The device will enter firmware update mode.")]
        UpdateFirmware = 0x20,

        /// <summary>
        /// Specifies that the device has booted from default factory values.
        /// </summary>
        [Description("Specifies that the device has booted from default factory values.")]
        BootFromDefault = 0x40,

        /// <summary>
        /// Specifies that the device has booted from non-volatile values stored in EEPROM.
        /// </summary>
        [Description("Specifies that the device has booted from non-volatile values stored in EEPROM.")]
        BootFromEeprom = 0x80
    }

    /// <summary>
    /// Specifies configuration flags for the device synchronization clock.
    /// </summary>
    [Flags]
    public enum ClockConfigurationFlags : byte
    {
        /// <summary>
        /// All clock configuration flags are cleared.
        /// </summary>
        [Description("All clock configuration flags are cleared.")]
        None = 0x0,

        /// <summary>
        /// The device will repeat the clock synchronization signal to the clock output connector, if
        /// available.
        /// </summary>
        [Description("The device will repeat the clock synchronization signal to the clock output connector, if available.")]
        ClockRepeater = 0x1,

        /// <summary>
        /// The device resets and generates the clock synchronization signal on the clock output connector,
        /// if available.
        /// </summary>
        [Description("The device resets and generates the clock synchronization signal on the clock output connector, if available.")]
        ClockGenerator = 0x2,

        /// <summary>
        /// Specifies the device has the capability to repeat the clock synchronization signal to the clock
        /// output connector.
        /// </summary>
        [Description("Specifies the device has the capability to repeat the clock synchronization signal to the clock output connector.")]
        RepeaterCapability = 0x8,

        /// <summary>
        /// Specifies the device has the capability to generate the clock synchronization signal to the
        /// clock output connector.
        /// </summary>
        [Description("Specifies the device has the capability to generate the clock synchronization signal to the clock output connector.")]
        GeneratorCapability = 0x10,

        /// <summary>
        /// The device will unlock the timestamp register counter and will accept commands to set new
        /// timestamp values.
        /// </summary>
        [Description("The device will unlock the timestamp register counter and will accept commands to set new timestamp values.")]
        ClockUnlock = 0x40,

        /// <summary>
        /// The device will lock the timestamp register counter and will not accept commands to set new
        /// timestamp values.
        /// </summary>
        [Description("The device will lock the timestamp register counter and will not accept commands to set new timestamp values.")]
        ClockLock = 0x80
    }

    /// <summary>
    /// Specifies the operation mode of the device.
    /// </summary>
    public enum OperationMode : byte
    {
        /// <summary>
        /// Disable all event reporting on the device.
        /// </summary>
        [Description("Disable all event reporting on the device.")]
        Standby = 0,

        /// <summary>
        /// Event detection is enabled. Only enabled events are reported by the device.
        /// </summary>
        [Description("Event detection is enabled. Only enabled events are reported by the device.")]
        Active = 1,

        /// <summary>
        /// The device enters speed mode.
        /// </summary>
        [Description("The device enters speed mode.")]
        Speed = 3
    }

    /// <summary>
    /// Specifies whether a specific register flag is enabled or disabled.
    /// </summary>
    public enum EnableFlag : byte
    {
        /// <summary>
        /// Specifies that the flag is disabled.
        /// </summary>
        [Description("Specifies that the flag is disabled.")]
        Disabled = 0,

        /// <summary>
        /// Specifies that the flag is enabled.
        /// </summary>
        [Description("Specifies that the flag is enabled.")]
        Enabled = 1
    }

    internal static partial class PayloadMarshal
    {
        internal static T[] GetSubArray<T>(T[] array, int offset, int count)
        {
            var result = new T[count];
            Array.Copy(array, offset, result, 0, count);
            return result;
        }

        internal static byte ReadByte(byte[] array, int offset) => array[offset];

        internal static sbyte ReadSByte(byte[] array, int offset) => (sbyte)array[offset];

        internal static ushort ReadUInt16(byte[] array, int offset) => BitConverter.ToUInt16(array, offset);

        internal static short ReadInt16(byte[] array, int offset) => BitConverter.ToInt16(array, offset);

        internal static uint ReadUInt32(byte[] array, int offset) => BitConverter.ToUInt32(array, offset);

        internal static int ReadInt32(byte[] array, int offset) => BitConverter.ToInt32(array, offset);

        internal static ulong ReadUInt64(byte[] array, int offset) => BitConverter.ToUInt64(array, offset);

        internal static long ReadInt64(byte[] array, int offset) => BitConverter.ToInt64(array, offset);

        internal static float ReadSingle(byte[] array, int offset) => BitConverter.ToSingle(array, offset);

        internal static string ReadUtf8String(byte[] array, int offset, int count)
        {
            var length = Array.IndexOf(array, (byte)0, offset, count) - offset;
            return System.Text.Encoding.UTF8.GetString(array, offset, length < 0 ? count : length);
        }

        internal static void Write(byte[] array, int offset, byte value) => array[offset] = value;

        internal static void Write(byte[] array, int offset, sbyte value) => array[offset] = (byte)value;

        internal static void Write(byte[] array, int offset, ushort value)
        {
            array[offset] = (byte)value;
            array[offset + 1] = (byte)(value >> 8);
        }

        internal static void Write(byte[] array, int offset, short value)
        {
            array[offset] = (byte)value;
            array[offset + 1] = (byte)(value >> 8);
        }

        internal static void Write(byte[] array, int offset, uint value)
        {
            array[offset] = (byte)value;
            array[offset + 1] = (byte)(value >> 8);
            array[offset + 2] = (byte)(value >> 16);
            array[offset + 3] = (byte)(value >> 24);
        }

        internal static void Write(byte[] array, int offset, int value)
        {
            array[offset] = (byte)value;
            array[offset + 1] = (byte)(value >> 8);
            array[offset + 2] = (byte)(value >> 16);
            array[offset + 3] = (byte)(value >> 24);
        }

        internal static void Write(byte[] array, int offset, ulong value)
        {
            array[offset] = (byte)value;
            array[offset + 1] = (byte)(value >> 8);
            array[offset + 2] = (byte)(value >> 16);
            array[offset + 3] = (byte)(value >> 24);
            array[offset + 4] = (byte)(value >> 32);
            array[offset + 5] = (byte)(value >> 40);
            array[offset + 6] = (byte)(value >> 48);
            array[offset + 7] = (byte)(value >> 56);
        }

        internal static void Write(byte[] array, int offset, long value)
        {
            array[offset] = (byte)value;
            array[offset + 1] = (byte)(value >> 8);
            array[offset + 2] = (byte)(value >> 16);
            array[offset + 3] = (byte)(value >> 24);
            array[offset + 4] = (byte)(value >> 32);
            array[offset + 5] = (byte)(value >> 40);
            array[offset + 6] = (byte)(value >> 48);
            array[offset + 7] = (byte)(value >> 56);
        }

        internal static unsafe void Write(byte[] array, int offset, float value) => Write(array, offset, *(int*)&value);

        internal static void Write(byte[] array, int offset, int count, string value) =>
            System.Text.Encoding.UTF8.GetBytes(value, 0, Math.Min(value.Length, count), array, offset);

        internal static void Write<T>(byte[] array, int offset, int count, T[] values) where T : unmanaged
        {
            Buffer.BlockCopy(values, 0, array, offset, count);
        }

        internal static void Write<T>(T[] array, int offset, int count, T[] values)
        {
            Array.Copy(values, 0, array, offset, count);
        }
    }
